import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def calculate_x_k(k, n):
    """Calculates x_k = lcm(k, k+1, ..., k+n-1)"""
    if n <= 0:
        return 1 # Or handle error

    current_lcm = k
    for i in range(k + 1, k + n):
        current_lcm = lcm(current_lcm, i)
    return current_lcm

def check_condition(n, max_k):
    """Checks x_{k+1} > x_k for k=1 to max_k"""
    smallest_failure_k = None

    # We need to calculate x_k and x_{k+1} for k up to max_k.
    # x_k uses numbers up to k+n-1.
    # x_{k+1} uses numbers up to k+1+n-1 = k+n.

    # We will compute all required x_k values and store them.
    x_values = {}

    # k runs from 1 up to max_k
    for k in range(1, max_k + 2): # Need x_k and x_{k+1}, so we need up to k+1 = max_k+1
        x_values[k] = calculate_x_k(k, n)

    # Now check the condition for k=1 to max_k
    for k in range(1, max_k + 1):
        x_k = x_values[k]
        x_k_plus_1 = x_values[k+1]

        if x_k_plus_1 <= x_k:
            smallest_failure_k = k
            break

    return smallest_failure_k

# Parameters
