results = {}

for n in N_values:
    failure_k = check_condition(n, MAX_K)
    results[n] = failure_k

print(results)

import math

# Helper function to calculate LCM of a list of numbers
def calculate_lcm_of_range(start, end):
    if start > end:
        return 1

    def lcm(a, b):
        return abs(a*b) // math.gcd(a, b)

    result = start
    for i in range(start + 1, end + 1):
        result = lcm(result, i)
    return result

def solve_task():
    N_values = [3, 4, 5]
    max_k = 100

    results = {}

    print("--- Starting Check ---")

    for n in N_values:
        smallest_k_failure = None

        print(f"\nChecking n = {n}...")

        for k in range(1, max_k + 1):
            # x_k = lcm(k, k+1, ..., k+n-1)
            x_k = calculate_lcm_of_range(k, k + n - 1)

            # x_{k+1} = lcm(k+1, k+2, ..., k+n)
            x_k_plus_1 = calculate_lcm_of_range(k + 1, k + n)

            # Check condition: x_{k+1} > x_k
            if x_k_plus_1 <= x_k:
                smallest_k_failure = k
                print(f"Failure found for n={n} at k={k}. x_k = {x_k}, x_{k+1} = {x_k_plus_1}")
                break

        results[n] = smallest_k_failure

    print("\n--- Results ---")
    for n, k_fail in results.items():
        print(f"For n={n}, smallest k where x_{k+1} <= x_k is: {k_fail} (None if no failure found up to k=100)")

    return results

if __name__ == "__main__":
    solve_task()
